import{_ as l,a0 as o,w as d,s as p,I as s,x as e,a1 as i,A as n,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"用 Linux 的 at 命令來安排一個任務 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux 的 at 命令來安排一個任務 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux 的 at 命令來安排一個任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux 的 at 命令來安排一個任務 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210815 Schedule a task with the Linux at command","title":"用 Linux 的 at 命令來安排一個任務","tag":"202108","desc":""},"relativePath":"202108/20210815 Schedule a task with the Linux at command.md","filePath":"[post].md"}'),h={name:"202108/20210815 Schedule a task with the Linux at command.md"};function r(u,a,g,k,b,m){const t=o("Link");return d(),p("div",null,[a[18]||(a[18]=s("h1",{id:"用-linux-的-at-命令來安排一個任務",tabindex:"-1"},[e("用 Linux 的 at 命令來安排一個任務 "),s("a",{class:"header-anchor",href:"#用-linux-的-at-命令來安排一個任務","aria-label":"Permalink to “用 Linux 的 at 命令來安排一個任務”"},"​")],-1)),a[19]||(a[19]=s("blockquote",null,[s("p",null,"at 命令是一種在特定時間和日期安排一次性任務的 Linux 終端方法。")],-1)),a[20]||(a[20]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/23/144542rmmyzwxsnanm4wpj.jpg",alt:""})],-1)),s("p",null,[a[1]||(a[1]=e("計算機擅長 ",-1)),i(t,{href:"https://opensource.com/article/20/11/orchestration-vs-automation"},{default:n(()=>[...a[0]||(a[0]=[e("自動化",-1)])]),_:1}),a[2]||(a[2]=e("，但不是每個人都知道如何使自動化工作。不過，能夠在特定的時間為電腦安排一個任務，然後忘記它，這確實是一種享受。也許你有一個文件要在特定的時間上傳或下載，或者你需要處理一批還不存在但可以保證在某個時間存在的文件，或者需要監控設置，或者你只是需要一個友好的提醒，在下班回家的路上買上面包和黃油。",-1))]),a[21]||(a[21]=c(`<p>這就是 <code>at</code> 命令的用處。</p><h3 id="什麼是-linux-at-命令" tabindex="-1">什麼是 Linux at 命令？ <a class="header-anchor" href="#什麼是-linux-at-命令" aria-label="Permalink to “什麼是 Linux at 命令？”">​</a></h3><p><code>at</code> 命令是在 Linux 終端讓你在特定時間和日期安排一次性工作的方法。它是一種自發的自動化，在終端上很容易實現。</p><h3 id="安裝-at" tabindex="-1">安裝 at <a class="header-anchor" href="#安裝-at" aria-label="Permalink to “安裝 at”">​</a></h3><p>在 Linux 上，<code>at</code> 命令可能已經安裝了。你可以使用 <code>at -V</code> 命令來驗證它是否已經安裝。只要返回一個版本號，就説明你已經安裝了 <code>at</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at -V</span></span>
<span class="line"><span>at version x.y.z</span></span></code></pre></div><p>如果你試圖使用 <code>at</code>，但沒有找到該命令，大多數現代的 Linux 發行版會為你提供缺少的 <code>at</code> 軟件包。</p><p>你可能還需要啓動 <code>at</code> 守護程序，稱為 <code>atd</code>。在大多數 Linux 系統中，你可以使用 <code>systemctl</code> 命令來啓用該服務，並將它們設置為從現在開始自動啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now atd</span></span></code></pre></div><h3 id="用-at-交互式地安排一個作業" tabindex="-1">用 at 交互式地安排一個作業 <a class="header-anchor" href="#用-at-交互式地安排一個作業" aria-label="Permalink to “用 at 交互式地安排一個作業”">​</a></h3><p>當你使用 <code>at</code> 命令並加上你希望任務運行的時間，會打開一個交互式 <code>at</code> 提示符。你可以輸入你想在指定時間運行的命令。</p><p>做個比喻，你可以把這個過程看作是一個日曆應用，就像你在你的手機上使用的那樣。首先，你在某一天的某個時間創建一個事件，然後指定你想要發生什麼。</p><p>例如，可以試試創建一個未來幾分鐘的任務，來給自己計劃一個備忘錄。這裏運行一個簡單的任務，以減少失敗的可能性。要退出 <code>at</code> 提示符，請按鍵盤上的 <code>Ctrl+D</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at 11:20 AM</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo &quot;hello world&quot; &gt; ~/at-test.txt</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 3 at Mon Jul 26 11:20:00 2021</span></span></code></pre></div><p>正如你所看到的，<code>at</code> 使用直觀和自然的時間定義。你不需要用 24 小時制的時鐘，也不需要把時間翻譯成 UTC 或特定的 ISO 格式。一般來説，你可以使用你自然想到的任何符號，如 <code>noon</code>、<code>1:30 PM</code>、<code>13:37</code> 等等，來描述你希望一個任務發生的時間。</p><p>等待幾分鐘，然後在你創建的文件上運行 <code>cat</code> 或者 <code>tac</code> 命令，驗證你的任務是否已經運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/at-test.txt</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="用-at-安排一個任務" tabindex="-1">用 at 安排一個任務 <a class="header-anchor" href="#用-at-安排一個任務" aria-label="Permalink to “用 at 安排一個任務”">​</a></h3><p>你不必使用 <code>at</code> 交互式提示符來安排任務。你可以使用 <code>echo</code> 或 <code>printf</code> 向它傳送命令。在這個例子中，我使用了 <code>now</code> 符號，以及我希望任務從現在開始延遲多少分鐘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;echo &#39;hello again&#39; &gt;&gt; ~/at-test.txt&quot; | at now +1 minute</span></span></code></pre></div><p>一分鐘後，驗證新的命令是否已被執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/at-test.txt</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello again</span></span></code></pre></div><h3 id="時間表達式" tabindex="-1">時間表達式 <a class="header-anchor" href="#時間表達式" aria-label="Permalink to “時間表達式”">​</a></h3><p><code>at</code> 命令在解釋時間時是非常寬容的。你可以在許多格式中選擇，這取決於哪一種對你來説最方便：</p><ul><li><code>YYMMDDhhmm[.ss]</code>（兩位的年份、月、日、小時、分鐘，及可選的秒）</li><li><code>CCYYMMDDhhmm[.ss]</code>（四位的年份、月、日、時、分鐘，及可選的秒）</li><li><code>now</code>（現在）</li><li><code>midnight</code>（午夜 00:00）</li><li><code>noon</code>（中午 12:00）</li><li><code>teatime</code>（下午 16 點）</li><li><code>AM</code>（上午）</li><li><code>PM</code>（下午）</li></ul><p>時間和日期可以是絕對時間，也可以加一個加號（<code>+</code>），使其與 <code>now</code> 相對。當指定相對時間時，你可以使用你可能用過的詞語：</p><ul><li><code>minutes</code>（分鐘）</li><li><code>hours</code>（小時）</li><li><code>days</code>（天）</li><li><code>weeks</code>（星期）</li><li><code>months</code>（月）</li><li><code>years</code>（年）</li></ul><h3 id="時間和日期語法" tabindex="-1">時間和日期語法 <a class="header-anchor" href="#時間和日期語法" aria-label="Permalink to “時間和日期語法”">​</a></h3><p><code>at</code> 命令對時間的輸入相比日期不那麼寬容。時間必須放在第一位，接着是日期，儘管日期默認為當前日期，並且只有在為未來某天安排任務時才需要。</p><p>這些是一些有效表達式的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;rsync -av /home/tux me@myserver:/home/tux/&quot; | at 3:30 AM tomorrow</span></span>
<span class="line"><span>$ echo &quot;/opt/batch.sh ~/Pictures&quot; | at 3:30 AM 08/01/2022</span></span>
<span class="line"><span>$ echo &quot;echo hello&quot; | at now + 3 days</span></span></code></pre></div><h3 id="查看你的-at-隊列" tabindex="-1">查看你的 at 隊列 <a class="header-anchor" href="#查看你的-at-隊列" aria-label="Permalink to “查看你的 at 隊列”">​</a></h3><p>當你愛上了 <code>at</code>，並且正在安排任務，而不是在桌子上的廢紙上亂寫亂畫，你可能想查看一下你是否有任務還在隊列中。</p><p>要查看你的 <code>at</code> 隊列，使用 <code>atq</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atq</span></span>
<span class="line"><span>10 Thu Jul 29 12:19:00 2021 a tux</span></span>
<span class="line"><span>9 Tue Jul 27 03:30:00 2021 a tux</span></span>
<span class="line"><span>7 Tue Jul 27 00:00:00 2021 a tux</span></span></code></pre></div><p>要從隊列中刪除一個任務，使用 <code>atrm</code> 命令和任務號。例如，要刪除任務 7：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ atrm 7</span></span>
<span class="line"><span>$ atq</span></span>
<span class="line"><span>10 Thu Jul 29 12:19:00 2021 a tux</span></span>
<span class="line"><span>9 Tue Jul 27 03:30:00 2021 a tux</span></span></code></pre></div><p>要看一個計劃中的任務的實際內容，你需要查看 <code>/var/spool/at</code> 下的內容。只有 root 用户可以查看該目錄的內容，所以你必須使用 <code>sudo</code> 來查看或 <code>cat</code> 任何任務的內容。</p><h3 id="用-linux-at-安排任務" tabindex="-1">用 Linux at 安排任務 <a class="header-anchor" href="#用-linux-at-安排任務" aria-label="Permalink to “用 Linux at 安排任務”">​</a></h3><p><code>at</code> 系統是一個很好的方法，可以避免忘記在一天中晚些時候運行一個作業，或者在你離開時讓你的計算機為你運行一個作業。與 <code>cron</code> 不同的是，它不像 <code>cron</code> 那樣要求任務必須從現在起一直按計劃運行到永遠，因此它的語法比 <code>cron</code> 簡單得多。</p><p>等下次你有一個希望你的計算機記住並管理它的小任務，試試 <code>at</code> 命令。</p><hr>`,42)),s("p",null,[a[4]||(a[4]=e("via: ",-1)),i(t,{href:"https://opensource.com/article/21/8/linux-at-command"},{default:n(()=>[...a[3]||(a[3]=[e("https://opensource.com/article/21/8/linux-at-command",-1)])]),_:1})]),s("p",null,[a[9]||(a[9]=e("作者：",-1)),i(t,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[5]||(a[5]=[e("Seth Kenlon",-1)])]),_:1}),a[10]||(a[10]=e(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[6]||(a[6]=[e("lujun9972",-1)])]),_:1}),a[11]||(a[11]=e(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:n(()=>[...a[7]||(a[7]=[e("geekpi",-1)])]),_:1}),a[12]||(a[12]=e(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[8]||(a[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[15]||(a[15]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[13]||(a[13]=[e("LCTT",-1)])]),_:1}),a[16]||(a[16]=e(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[14]||(a[14]=[e("Linux中國",-1)])]),_:1}),a[17]||(a[17]=e(" 榮譽推出",-1))])])}const C=l(h,[["render",r]]);export{y as __pageData,C as default};
